# generate square + L placements with colors; backtracking exact cover, any number
shapes=[]
for r in range(6):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: shapes.append((sq,1))
  box={(r+i,c+j) for i in range(2) for j in range(2)}
  for missing,col in [((r,c),2),((r,c+1),3),((r+1,c),4),((r+1,c+1),5)]:
   sh=box-{missing}
   if sh<=cells: shapes.append((sh,col))
sol=[]
def rec(rem, chosen):
 if not rem: sol.append(chosen); return True
 x=min(rem,key=lambda p:sum(x<=rem for x,col in shapes if p in x))
 for sh,col in shapes:
  if x in sh and sh<=rem:
   if rec(rem-sh,chosen+[(sh,col)]): return True
 return False
rec(cells,[])
